{"task": "Find all log messages that contain a MAC address", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}')"}
{"task": "Count log entries containing a MAC address grouped by service", "sql": "SELECT service, COUNT(*) AS mac_log_count FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}') GROUP BY service ORDER BY mac_log_count DESC"}
{"task": "Find error-level logs that contain a MAC address formatted with hyphens", "sql": "SELECT ts, service, message FROM logs WHERE level = 'ERROR' AND regexp_like(message, '([0-9A-Fa-f]{2}-){5}[0-9A-Fa-f]{2}')"}
{"task": "Classify each log line as containing a colon-separated or hyphen-separated MAC address or neither", "sql": "SELECT ts, service, message, CASE WHEN regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}') THEN 'colon' WHEN regexp_like(message, '([0-9A-Fa-f]{2}-){5}[0-9A-Fa-f]{2}') THEN 'hyphen' ELSE 'none' END AS mac_format FROM logs"}
{"task": "Find logs mentioning MAC addresses case-insensitively in messages that also mention 'dhcp'", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([0-9a-f]{2}:){5}[0-9a-f]{2}', 'i') AND regexp_like(message, 'dhcp', 'i')"}
{"task": "Find the most recent 50 log entries containing a MAC address", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}') ORDER BY ts DESC LIMIT 50"}
{"task": "Find logs with a MAC address that also indicate an authentication failure", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}') AND regexp_like(message, 'auth(entication)? failed', 'i')"}
{"task": "Count distinct services whose logs ever contain a MAC address", "sql": "SELECT COUNT(DISTINCT service) AS services_with_mac FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}')"}
{"task": "Find logs that contain a MAC address but do not mention an IP address, to spot possible L2-only events", "sql": "SELECT ts, service, message FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}') AND NOT regexp_like(message, '([0-9]{1,3}\\.){3}[0-9]{1,3}')"}
{"task": "Find the daily count of log messages containing a MAC address over the last 7 days", "sql": "SELECT DATE_TRUNC('day', ts) AS day, COUNT(*) AS mac_log_count FROM logs WHERE regexp_like(message, '([0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}') AND ts >= NOW() - INTERVAL '7 days' GROUP BY day ORDER BY day"}

